return ['x-generator'=>'GlotPress/4.0.1','translation-revision-date'=>'2020-04-12 14:44:14+0000','plural-forms'=>'nplurals=2; plural=n > 1;','project-id-version'=>'Plugins - Movable Type and TypePad Importer - Stable (latest release)','language'=>'fr','messages'=>['http://wordpress.org/'=>'http://wordpress.org/','wordpressdotorg'=>'wordpressdotorg','http://wordpress.org/extend/plugins/movabletype-importer/'=>'http://wordpress.org/extend/plugins/movabletype-importer/','Movable Type and TypePad Importer'=>'Importateur Movable Type et TypePad','Import posts and comments from a Movable Type or TypePad blog.'=>'Importation d&rsquo;articles et de commentaires depuis un blog Movable Type ou TypePad.','Movable Type and TypePad'=>'Movable Type et TypePad','All done. <a href="%s">Have fun!</a>'=>'Terminé&nbsp;! (<a href="%s">Amusez-vous bien&nbsp;!</a>)','(%s ping)'=>'(%s ping)' . "\0" . '(%s pings)','(%s comment)'=>'(%s commentaire)' . "\0" . '(%s commentaires)','Adding tags <em>%s</em>...'=>'Ajout des mots-clefs <em>%s</em>...','Importing post <em>%s</em>...'=>'Importation de l&rsquo;article <em>%s</em>&hellip;','Post <em>%s</em> already exists.'=>'L&rsquo;article <em>%s</em> existe déjà.','Sorry, there has been an error'=>'Désolé, il y a eu une erreur','<code>mt-export.txt</code> does not exist'=>'<code>mt-export.txt</code> n&rsquo;existe pas','Submit'=>'Envoyer','Create user %1$s or map to existing'=>'Création de l&rsquo;utilisateur %1$s, ou mise en correspondance avec l&rsquo;existant','Current author:'=>'Auteur actuel&nbsp;:','If a new user is created by WordPress, a password will be randomly generated. Manually change the user&#8217;s details if necessary.'=>'Si un nouvel utilisateur est créé par WordPress, un mot de passe sera généré aléatoirement. Vous pouvez modifier manuellement les détails de l&rsquo;utilisateur si besoin.','Below, you can see the names of the authors of the Movable Type posts in <em>italics</em>. For each of these names, you can either pick an author in your WordPress installation from the menu, or enter a name for the author in the textbox.'=>'Ci-dessous, vous pouvez voir les noms des auteurs des articles de Movable Type en<em>italique</em>. Pour chacun de ces noms, vous pouvez soit choisir à partir du menu un auteur de votre installation de WordPress, soit saisissez un nom pour l’auteur dans le champ.','To make it easier for you to edit and save the imported posts and drafts, you may want to change the name of the author of the posts. For example, you may want to import all the entries as admin&#8217;s entries.'=>'De façon à vous faciliter la modification et validation des articles importés et des brouillons, il se peut que vous vouliez changer le nom des auteurs des articles. Par exemple, vous pourriez importer tous les articles comme articles de l&rsquo;<code>admin</code>.','Assign Authors'=>'Assigner les auteurs','&mdash; Select &mdash;'=>'&mdash; Sélectionner &mdash;','The importer is smart enough not to import duplicates, so you can run this multiple times without worry if&#8212;for whatever reason&#8212;it doesn&#8217;t finish. If you get an <strong>out of memory</strong> error try splitting up the import file into pieces.'=>'L&rsquo;outil d&rsquo;importation est suffisamment intelligent pour ne pas importer les doublons, donc vous pouvez le lancer plusieurs fois sans vous soucier s&rsquo;il s&rsquo;interrompait en cours de route, pour n&rsquo;importe quelle raison. Si vous obtenez une erreur <strong>manque de mémoire</strong>, essayez de découper le fichier à importer en plusieurs morceaux.','Import mt-export.txt'=>'Importer mt-export.txt','Or use <code>mt-export.txt</code> in your <code>/wp-content/</code> directory'=>'Ou placez <code>mt-export.txt</code> dans votre dossier <code>/wp-content/</code> ','Howdy! We are about to begin importing all of your Movable Type or TypePad entries into WordPress. To begin, either choose a file to upload and click &#8220;Upload file and import&#8221;, or use FTP to upload your MT export file as <code>mt-export.txt</code> in your <code>/wp-content/</code> directory and then click &#8220;Import mt-export.txt&#8221;.'=>'Salutations&nbsp;! Nous allons importer toutes vos entrées de Movable Type ou TypePad dans WordPress. Pour commencer, choisissez le fichier à mettre en ligne et cliquez sur &laquo;&nbsp;Mettre en ligne et importer&nbsp;&raquo;&nbsp;; ou passez par votre client FTP pour mettre votre fichier d&rsquo;export MT, renommé <code>mt-export.txt</code>, dans le dossier <code>/wp-content/</code>, puis cliquez sur &laquo;&nbsp;Importer mt-export.txt&nbsp;&raquo;&nbsp;','Import Movable Type or TypePad'=>'Importation depuis Movable Type ou TypePad']];